payment_url = f"{frappe.utils.get_url()}/api/method/frappe.www.payment.process?token={doc.name}"

# 获取 doc 的所有字段和值
doc_fields = doc.as_dict()

# 遍历所有字段，替换 {{ doc.xxx }} 变量
for key, value in doc_fields.items():
    if isinstance(value, (int, float)):
        value = str(value)
    elif not isinstance(value, str):
        continue  # 只处理字符串和数字
    placeholder = f"{{{{ doc.{key} }}}}"
    doc.message = doc.message.replace(placeholder, value)

# 单独处理 {{ payment_url }}
doc.message = doc.message.replace("{{ payment_url }}", payment_url)
